(function(){
 'use strict';
 const root=document.getElementById('rodavolt'),main=root.querySelector('#content'),dialog=root.querySelector('#detail'),S=globalThis.RodavoltSimulator,C=globalThis.RodavoltControl,T=globalThis.RodavoltStrategy,P=globalThis.RodavoltPlanning,M=globalThis.RodavoltOperations,D=globalThis.RodavoltDriver;
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>n===null||n===undefined?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(n),money=n=>n===null||n===undefined?'—':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n),cash=n=>n===null||n===undefined?'—':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n),pct=n=>n===null?'Sem base':num(n)+'%',date=s=>s?String(s).split('-').reverse().join('/'):'—';
 const pages={today:'Visão do dia',drivers:'Motoristas',fleet:'Frota e cuidados',finance:'Financeiro',shop:'Loja no carro',simulator:'Simulador de crescimento',compare:'Planejado × realizado'};
 const categories={rent:'Aluguel recebido',shop:'Venda da loja',shopCost:'Mercadoria',commission:'Comissão',opex:'Despesa operacional',tax:'Tributos',interest:'Juros',principal:'Principal da dívida',contribution:'Aporte',capex:'Aquisição de carro'};
 let params={...P.defaults},baseline=S.freezePlan(P.defaults,'PLANO-001'),ops=M.create(baseline),savedScenarios=[],scenarioName='Compra do primeiro carro',page='today',mode='admin',driverPage='home',flowMode='annual',month=3,driverFilter='',driverLayout='board',financeTab='charges',revision=null,report=P.report(params),ride={amount:32,tripKm:10,pickupKm:2,returnKm:0,tripMin:22,pickupMin:6,waitMin:2,returnMin:0,toll:0},rideResult=D.evaluate({amount:32,tripKm:10,pickupKm:2,tripMin:22,pickupMin:6,waitMin:2},D.defaults),draggedId=null,toastTimer,simTimer;
 const isQA=new URLSearchParams(location.search).has('qa'),storageKey='rodavolt-v3';
 function restore(state){if(!state||state.version!==3)return;try{const p=S.validate(state.params),b=S.freezePlan(state.baseline.params,state.baseline.id,state.baseline.createdAt);if(state.ops?.schema!==3)throw new Error('Estado incompatível');D.validate(state.ops.personal.settings);params=p;baseline=b;ops=state.ops;savedScenarios=(state.savedScenarios||[]).map(c=>({...c,params:S.validate(c.params)}));scenarioName=String(state.scenarioName||scenarioName);if(pages[state.page])page=state.page;if(['admin','driver'].includes(state.mode))mode=state.mode;if(driverNames[state.driverPage])driverPage=state.driverPage;}catch{toast('Não foi possível restaurar esta sessão. Os dados anteriores continuam no navegador; exporte antes de reiniciar.');}}
 function persist(){if(isQA)return true;try{localStorage.setItem(storageKey,JSON.stringify({version:3,params,baseline:{params:baseline.params,id:baseline.id,createdAt:baseline.createdAt},ops,savedScenarios,scenarioName,page,mode,driverPage}));return true;}catch{toast('Armazenamento indisponível. Exporte os dados para preservar esta sessão.');return false;}}
 function reportError(message){if(dialog.open){let e=dialog.querySelector('[data-dialog-error]');if(!e){e=document.createElement('p');e.className='notice red';e.setAttribute('role','alert');e.dataset.dialogError='true';root.querySelector('#detail-content').prepend(e);}e.textContent=message;}else toast(message);}
 function toast(message){const e=root.querySelector('#toast');e.textContent=message;e.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.hidden=true,5500);}
 const btn=(label,action,style='',extra='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`,link=(label,action,extra='')=>`<button type="button" class="link" data-action="${action}" ${extra}>${label}</button>`,tag=(label,style='')=>`<span class="tag ${style}">${label}</span>`;
 const heading=(over,title,desc,actions='')=>`<div class="heading"><div><span class="eyebrow">${over}</span><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;
 const panel=(title,body,side='',desc='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${side}</div>${body}</section>`;
 const section=(title,description='',side='')=>`<div class="section-title"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${side}</div>`;
 const row=(label,value,detail='',total=false)=>`<div class="row ${total?'total':''}"><div>${label}${detail?`<small>${detail}</small>`:''}</div><strong>${value}</strong></div>`;
 const stat=(label,value,detail,featured=false,action='')=>`<div class="stat ${featured?'featured':''}"><div class="stat-label">${label}${action?link('↗',action,`aria-label="Ver origem de ${esc(label)}"`):''}</div><strong>${value}</strong><small>${detail}</small></div>`;
 const input=(name,label,value,options='')=>`<label class="field">${label}<input name="${name}" value="${esc(value)}" ${options}></label>`;
 const select=(name,label,value,options,extra='')=>`<label class="field">${label}<select name="${name}" ${extra}>${options.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('')}</select></label>`;
 const table=(headers,rows,extra='')=>`<div class="table-wrap"><table ${extra}><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;
 const segments=(options,value,attr)=>`<div class="segments">${options.map(([k,label])=>`<button type="button" data-${attr}="${k}" aria-pressed="${k===value}">${label}</button>`).join('')}</div>`;
 const initials=name=>esc(name.split(' ').slice(0,2).map(s=>s[0]).join(''));
 function summary(){return M.summary(ops,baseline);}function actual(){return C.realized(ops.book,baseline).find(r=>r.month===month)||C.realized(ops.book,baseline).at(-1);}
 function period(){return select('period','Fechamento demonstrativo',String(month),[1,2,3].map(m=>[String(m),S.label(ops.book.calendar,m)]),'data-period="true"');}
 function open(title,body){root.querySelector('#detail-title').textContent=title;root.querySelector('#detail-content').innerHTML=body;if(!dialog.open)dialog.showModal();}function close(){if(dialog.open)dialog.close();}
 function download(filename,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function task(symbol,title,description,action,label='Abrir'){return `<div class="task"><span class="task-icon" aria-hidden="true">${symbol}</span><div><h3>${title}</h3><p>${description}</p></div>${btn(label,action)}</div>`;}
 function chart(id,title,legend,description=''){const colors=['#21865e','#91b3a0','#8fa7c3','#bd9861','#76827c'];return panel(title,`<svg class="chart" data-chart="${id}" role="img" aria-label="${title}"></svg><div class="chart-legend">${legend.map((t,i)=>`<span><i style="background:${colors[i]}"></i>${t}</span>`).join('')}</div>${description?`<p class="caption">${description}</p>`:''}`);}
 function today(){const s=summary(),a=s.actual;return heading('JANEIRO DE 2027 · OPERAÇÃO ILUSTRATIVA','Seu dia, em ordem.','O que precisa de atenção agora, com acesso direto à ação certa.',btn('Novo lançamento','expense','primary'))+`<div class="stats">${stat('Aluguel recebido no mês',money(a.rentalReceived),'Somente recebimentos confirmados',false,'ledger')}${stat('Caixa no fechamento',money(a.cash),'Saldo rastreável do livro demonstrativo',true,'cash-source')}${stat('Aluguel a receber',money(s.openRent),s.pendingProofs?s.pendingProofs+' comprovante(s) em conferência':'Próxima cobrança · 25 de janeiro')}${stat('Carros na operação',String(a.fleet),s.active+' motorista(s) com vínculo ativo')}</div><div class="columns-main"><div class="stack">${panel('Sua fila de atenção',task('＄','Conferir o aluguel da semana',s.openRent>0?money(s.openRent)+' em aberto · cobrança COB-4':'Cobranças de exemplo conferidas.','go-finance','Conferir')+task('▥','Avançar o cadastro dos motoristas',s.pipeline+' interessados entre contato, documentação e entrega.','go-drivers','Ver kanban')+task('▱','Acompanhar a próxima manutenção',num(Math.max(0,ops.vehicle.nextKm-ops.vehicle.km))+' km até a próxima revisão do RV-001.','go-fleet','Ver carro')+(s.requests?task('◷','Responder solicitações do motorista',s.requests+' pedido(s) aberto(s), com histórico e responsável.','requests','Atender'):''),tag('ROTINA DA LOCADORA','green'))}${chart('day-cash','Seu caixa, com contexto',['Plano preservado','Registros de exemplo'],'A diferença pode vir de uma compra adiada, manutenção ou recebimento. Abra a comparação para conferir as origens.')}</div><div class="stack"><section class="daily-hero"><div><span class="small-label">ANTES DO PRÓXIMO INVESTIMENTO</span><h2>Mais um carro.<br>Quanto ele muda o plano?</h2><p>Veja entradas, custos, dívida e crescimento antes de comprometer seu capital.</p>${btn('Simular o próximo passo ↗','go-simulator')}</div></section>${panel('RV-001 · seu carro em operação',`<div class="vehicle-line"><span class="vehicle-symbol" aria-hidden="true">▱</span><div><h3>HB20 Sense</h3><small>2023 · ${ops.vehicle.plate}</small></div></div>`+row('Motorista','Marcos Oliveira')+row('Aluguel semanal',money(ops.book.contract.weekly))+row('Hodômetro',num(ops.vehicle.km)+' km')+row('Situação',tag(ops.vehicle.status==='maintenance'?'Em manutenção':'Com motorista',ops.vehicle.status==='maintenance'?'amber':'green'))+link('Abrir ficha e cuidados →','go-fleet'))}${panel('Loja no carro',row('Produtos do kit','Perfumes e acessórios','Estoque, comissão e repasse separados do aluguel.')+row('Vendas em acerto',money(s.shop.gross))+row('Comissão a conferir',cash(s.shop.commission))+link('Abrir estoque e vendas →','go-shop'))}</div></div>`;}
 function drivers(){const list=ops.drivers.filter(d=>!driverFilter||(d.name+' '+d.interest+' '+d.note).toLowerCase().includes(driverFilter.toLowerCase()));return heading('RELACIONAMENTO E ENTREGA','Cada motorista, no próximo passo.','Um fluxo do primeiro contato à devolução. Arraste entre etapas ou abra o cartão para mover com o teclado.',btn('Adicionar motorista','add-driver','primary'))+`<div class="filter-row">${input('driverSearch','Buscar no kanban',driverFilter,'type="search" placeholder="Nome, interesse ou observação" class="inline-search" data-driver-filter="true"')}${segments([['board','Kanban'],['list','Lista']],driverLayout,'driver-layout')}</div><div id="driver-board">${driverLayout==='board'?`<div class="board-wrap"><div class="board">${M.stages.map(([key,label])=>`<section class="lane" data-stage="${key}" aria-label="${label}"><div class="lane-head"><span><i class="lane-dot"></i>${label}</span><small>${list.filter(d=>d.stage===key).length}</small></div>${list.filter(d=>d.stage===key).map(driverCard).join('')||'<div class="empty-lane">Nenhum motorista nesta etapa</div>'}</section>`).join('')}</div></div>`:table(['Motorista','Etapa','Próxima ação','Conferências','Abrir'],list.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.interest)}</small></td><td>${M.stages.find(([k])=>k===d.stage)[1]}</td><td>${esc(d.note)}</td><td>Documentos ${d.docs?'✓':'pendentes'}<small>Contrato ${d.signed?'✓':'pendente'} · vistoria ${d.inspection?'✓':'pendente'}</small></td><td>${btn('Abrir ficha','driver-detail','',`data-id="${d.id}"`)}</td></tr>`).join(''))}</div><div class="notice gap">Entrar em “Rodando” exige documentos, contrato e vistoria conferidos, além de carro disponível. A decisão de aprovação é sua; o sistema não atribui nota automática às pessoas.</div>`;}
 function driverCard(d){return `<article class="driver-card draggable" draggable="true" data-driver-card="${d.id}"><div class="card-name"><span class="avatar">${initials(d.name)}</span><strong>${esc(d.name)}</strong></div><p>${esc(d.note)}</p>${tag(d.vehicleId||d.interest,d.stage==='active'?'green':d.stage==='ready'?'amber':'')}<div class="card-foot"><span>${date(d.due).slice(0,5)} · próxima ação</span>${link('Abrir →','driver-detail',`data-id="${d.id}"`)}</div></article>`;}
 function driverForm(d=null){return `<form id="driver-form">${d?`<input type="hidden" name="entityId" value="${d.id}">`:''}<div class="fields">${input('name','Nome',d?.name||'','required maxlength="100"')}${input('interest','Interesse',d?.interest||'Aluguel semanal','maxlength="100"')}${input('due','Data da próxima ação',d?.due||'2027-01-26','type="date" required')}${d?select('stage','Etapa do fluxo',d.stage,M.stages)+select('nextVehicleId','Carro para a entrega',d.vehicleId||d.nextVehicleId||'RV-001',M.vehicles(ops).map(v=>[v.id,v.id+' · '+v.model+' · '+(v.status==='available'?'disponível':v.status==='maintenance'?'manutenção':'vinculado')])):''}</div><label class="field gap">Próxima ação e observações<textarea name="note" rows="3" maxlength="500">${esc(d?.note||'')}</textarea></label>${d?`<div class="gap"><h3>Conferências da entrega</h3>${[['docs','Documentação conferida'],['signed','Contrato conferido e assinado'],['inspection','Vistoria de entrega conferida']].map(([key,label])=>`<label class="check"><input type="checkbox" name="${key}" ${d[key]?'checked':''}>${label}</label>`).join('')}<p class="caption">Checklist demonstrativo. Nenhum documento pessoal ou assinatura é armazenado nesta versão.</p></div>`:''}<div class="form-actions"><button type="submit" class="btn primary">${d?'Salvar e atualizar etapa':'Criar cartão'}</button></div></form>`;}
 function fleet(){const a=actual(),v=ops.vehicle;return heading('DISPONIBILIDADE E CUSTO','Carro rodando. Cuidado em dia.','A mesma ficha reúne financiamento, contrato, hodômetro, manutenção e vistoria.',btn('Registrar aquisição','acquire','primary'))+`<div class="stats">${stat('Frota registrada',String(a.fleet),'Ativos do fechamento demonstrativo')}${stat('Valor dos carros',money(a.assets),'Estimativa com depreciação do cenário')}${stat('Dívida em aberto',money(a.debt),'Saldo por veículo após principal pago')}${stat('Próxima revisão',num(Math.max(0,v.nextKm-v.km))+' km','RV-001 · '+num(v.nextKm)+' km')}</div>${panel('Sua frota',table(['Veículo','Vínculo','Valor estimado','Dívida','Idade na simulação'],a.snapshot.cars.map(car=>`<tr><td><strong>${esc(M.vehicles(ops).find(v=>v.id===car.id)?.model||car.id)}</strong><small>${esc(M.vehicles(ops).find(v=>v.id===car.id)?.plate||car.id)}</small></td><td>${tag(M.vehicles(ops).find(v=>v.id===car.id)?.status==='maintenance'?'Manutenção':ops.drivers.find(d=>d.stage==='active'&&d.vehicleId===car.id)?.name||'Disponível',M.vehicles(ops).find(v=>v.id===car.id)?.status==='maintenance'?'amber':'green')}</td><td>${money(car.value)}</td><td>${money(car.debt)}</td><td>${car.age} meses</td></tr>`).join('')))}<div class="grid2 gap">${panel('Manutenção e serviços',ops.service.length?ops.service.map(s=>row(esc(s.title),tag(s.status==='open'?'Em andamento':'Concluído',s.status==='open'?'amber':'green'),s.id+(s.status==='closed'?' · '+money(s.cost):''))+(s.status==='open'?btn('Concluir e registrar custo','service-close','',`data-id="${s.id}"`):'')).join(''):'<p class="caption">Nenhuma ordem aberta nesta demonstração.</p>',btn('Abrir manutenção','service-open'))}${panel('Entrega e devolução',row('Contrato do exemplo','LOC-001 · Marcos','Aluguel semanal, responsabilidades e kit comercial.')+row('Vistorias registradas',String(ops.checklists.length),'Checklist e hodômetro. Fotos e assinatura dependem da implementação operacional.')+btn('Ver contrato e responsabilidades','contract')+btn('Ver solicitações e vistorias','requests'))}</div>`;}
 function finance(){const a=actual(),s=summary();return heading('RECEBER, PAGAR, CONFERIR','Dinheiro com destino e origem.','Cobrança em aberto, comprovante enviado e recebimento confirmado são estados diferentes.',btn('Novo lançamento','expense','primary'))+`<div class="stats">${stat('Recebido no fechamento',money(a.rentalReceived),'Aluguéis confirmados')}${stat('Em aberto',money(s.openRent),'Cobranças do exemplo ainda não baixadas')}${stat('Caixa disponível',money(a.cash),'Abrir composição do fechamento',true,'cash-source')}${stat('Comprovantes em análise',String(s.pendingProofs),'Envio não confirma pagamento')}</div>${segments([['charges','Cobranças semanais'],['ledger','Livro de registros'],['proofs','Comprovantes']],financeTab,'finance-tab')}<div class="gap">${financeTab==='ledger'?ledgerView():financeTab==='proofs'?panel('Conferência de comprovantes',ops.proofs.length?ops.proofs.map(p=>row(p.id,tag(p.status==='pending'?'Em conferência':'Conferido',p.status==='pending'?'amber':'green'),esc(p.note))+(p.status==='pending'?btn('Conferir recebimento','pay','primary',`data-id="${p.chargeId}"`):'')).join(''):'<p class="caption">O motorista pode enviar um comprovante de exemplo na carteira. A confirmação acontece aqui.</p>'):panel('Agenda de aluguel · LOC-001',table(['Cobrança','Motorista','Vencimento','Valor','Situação','Ação'],ops.charges.map(c=>`<tr><td>${c.id}<small>${esc(c.source)}</small></td><td>Marcos Oliveira</td><td>${date(c.date)}</td><td>${cash(c.amount)}</td><td>${tag(c.status==='paid'?'Recebido':ops.proofs.some(p=>p.chargeId===c.id&&p.status==='pending')?'Comprovante em análise':'Em aberto',c.status==='paid'?'green':'amber')}</td><td>${c.status==='paid'?link('Ver origem','ledger'):btn('Confirmar recebimento','pay','',`data-id="${c.id}"`)}</td></tr>`).join('')))}</div><p class="caption">Sem integração bancária ou Pix nesta versão. Todas as confirmações são manuais e demonstrativas. Caução e assinatura reais dependem do contrato operacional.</p>`;}
 function ledgerView(){const entries=ops.book.entries.filter(e=>e.month===month);return panel('Livro demonstrativo · '+S.label(ops.book.calendar,month),table(['Registro','Natureza','Centro','Origem','Valor'],entries.map(e=>`<tr><td>${e.id}</td><td>${esc(categories[e.category]||e.category)}${e.cashEffect===false?'<small>Custo sem saída de caixa</small>':''}</td><td>${e.vehicle}</td><td>${esc(e.source)}</td><td>${cash(e.amount)}</td></tr>`).join('')),period());}
 function shop(){const s=M.shopSummary(ops);return heading('PERFUMARIA E ACESSÓRIOS','Uma segunda receita. Sob controle.','Perfumes, carregadores e cabos: do estoque central ao kit, da venda ao acerto com o motorista.',btn('Registrar venda','sale','primary'))+`<div class="stats">${stat('Vendas a conferir',cash(s.gross),s.sales+' venda(s) ainda em acerto')}${stat('Comissão do motorista',cash(s.commission),'Regra demonstrativa: '+ops.book.contract.commissionPct+'% das vendas')}${stat('Repasse à empresa',cash(s.remittance),'Vendas recebidas pelo motorista')}${stat('Margem do acerto',cash(s.margin),'Vendas − custo − comissão, antes de tributos',true)}</div><div class="grid3">${ops.book.products.map(p=>`<section class="product-card"><div class="product-art" aria-hidden="true"><div class="${p.id==='perfume'?'perfume-bottle':p.id==='charger'?'charger-art':'cable-art'}"></div></div>${tag(esc(p.category))}<h3 class="gap">${esc(p.name)}</h3><div class="price">${cash(p.price)}</div><p class="caption">Custo ${cash(p.cost)} · comissão conforme contrato do kit</p><div class="stock-counts gap"><span>Central <strong>${p.central} un.</strong></span><span>No carro <strong>${p.kit} un.</strong></span></div><div class="actions gap">${btn('Transferir para o carro','stock-transfer','',`data-id="${p.id}"`)}${p.kit<=p.min?tag('Estoque baixo','amber'):''}</div></section>`).join('')}</div><div class="grid2 gap">${panel('Acerto com o motorista',row('Vendas brutas',cash(s.gross))+row('Custo da mercadoria',cash(s.cost))+row('Comissão preservada nas vendas',cash(s.commission))+row('Motorista deve repassar',cash(s.remittance),'Quando recebeu em dinheiro; já descontada a comissão.')+row('Empresa deve pagar de comissão',cash(s.payable),'Quando o recebimento ficou com a empresa.')+btn('Conferir e fechar acerto','settle','primary',s.sales?'':'disabled')+'<p class="caption">A conferência lança o acerto uma única vez no livro de demonstração. Não compensa aluguel sem registro.</p>')}${panel('Vendas desta sessão',ops.book.sales.length?table(['Venda','Produto','Valor','Recebeu','Situação'],ops.book.sales.map(v=>`<tr><td>${v.id}<small>${v.qty} un.</small></td><td>${esc(v.productName)}</td><td>${cash(v.gross)}</td><td>${v.method==='driver'?'Motorista':'Empresa'}</td><td>${tag(v.settled?'Conferida':'Em acerto',v.settled?'green':'amber')}</td></tr>`).join('')):'<p class="caption">Nenhuma venda nesta sessão. O livro possui lançamentos de abertura ilustrativos; novas vendas usam este mesmo kit e estoque.</p>')}</div>`;}
 function compare(){const a=actual(),diffs=S.compare(baseline,C.realized(ops.book,baseline),month),labels={rentalReceived:'Aluguel recebido',storeGross:'Vendas da loja',opex:'Despesas operacionais',debtService:'Parcelas',capex:'Compras de carros',cash:'Caixa final',fleet:'Frota',debt:'Saldo devedor',equity:'Patrimônio estimado'};return heading('O PLANO ENCONTRA A OPERAÇÃO','Previsto, realizado e explicado.','O plano preservado continua intacto. Cada lançamento muda o realizado e a sua diferença.',period()+btn('Reestimar daqui para a frente','revise','primary'))+`<div class="notice">Referência: <strong>${esc(baseline.id)}</strong> · ${esc(S.label(baseline.params,1))} em diante. ${link('Preservar o cenário atual como nova referência','freeze')}</div><div class="grid2 gap">${chart('compare-cash','Caixa: plano e registros',['Plano preservado','Registros demonstrativos',...(revision?['Revisão']:[])])}${chart('compare-fleet','Evolução da frota',['Plano preservado','Registros demonstrativos'])}</div><div class="gap">${panel('Desvios no fechamento · '+a.label,table(['Indicador','Plano','Registros demo','Diferença','Desvio','Origem'],diffs.map(d=>`<tr><td>${labels[d.key]}</td><td>${d.key==='fleet'?num(d.projected):money(d.projected)}</td><td>${d.key==='fleet'?num(d.actual):money(d.actual)}</td><td>${d.key==='fleet'?num(d.delta):cash(d.delta)}</td><td>${d.percent===null?'Base zero / sem percentual':pct(d.percent)}</td><td>${link('Ver composição','metric-source',`data-key="${d.key}"`)}</td></tr>`).join('')))}</div>${revision?`<div class="notice gap">Revisão a partir de ${a.label}: frota final ${revision.final.fleet}, caixa ${money(revision.final.cash)} e patrimônio estimado ${money(revision.final.equity)}. A revisão usa caixa, idade e dívida do fechamento; o passado permanece preservado.</div>`:''}<p class="caption">Mais caixa pode significar uma compra adiada. Valor de carro é estimado, não cotação. Dados sem fonte não são convertidos em zero.</p>`;}
 /* SIMULATOR VIEW */
 /* DRIVER VIEW */
 let renderedView=null;
 function render(){const nextView=mode+':'+(mode==='driver'?driverPage:page),changed=nextView!==renderedView;renderedView=nextView;report=P.report(params);root.classList.toggle('is-driver',mode==='driver');root.querySelector('#page-name').textContent=mode==='driver'?'App do motorista':pages[page];root.querySelectorAll('[data-page]').forEach(e=>e.setAttribute('aria-current',mode==='admin'&&e.dataset.page===page?'page':'false'));main.innerHTML=mode==='driver'?driverView():({today,drivers,fleet,finance,shop,simulator,compare}[page])();drawCharts();if(changed)window.scrollTo({top:0,behavior:'instant'});}
 function chartDefinitions(){const r=report.result,b=baseline.projection.months,a=C.realized(ops.book,baseline),month0=report.initial;return {'day-cash':{max:3,series:[{name:'Plano',data:b.filter(m=>m.month<=3).map(m=>[m.month,m.cash])},{name:'Registros',data:a.map(m=>[m.month,m.cash])}]},'compare-cash':{max:12,series:[{name:'Plano',data:b.filter(m=>m.month<=12).map(m=>[m.month,m.cash])},{name:'Registros',data:a.filter(m=>m.month<=month).map(m=>[m.month,m.cash])},...(revision?[{name:'Revisão',data:[[month,actual().cash],...revision.months.filter(m=>m.month<=12).map(m=>[m.month,m.cash])]}]:[])]},'compare-fleet':{max:12,unit:'carros',step:true,series:[{name:'Plano',data:b.filter(m=>m.month<=12).map(m=>[m.month,m.fleet])},{name:'Registros',data:a.map(m=>[m.month,m.fleet])}]},'sim-cashflow':{max:params.horizon,series:[{name:'Entradas',data:r.months.map(m=>[m.month,m.rentalReceived+m.storeGross])},{name:'Despesas',data:report.monthly.map(m=>[m.month,m.costs])},{name:'Parcela',data:r.months.map(m=>[m.month,m.debtService])},{name:'Lucro',data:r.months.map(m=>[m.month,m.result])}]},'sim-assets':{max:params.horizon,series:[{name:'Valor dos carros',data:[[0,month0.assets],...r.months.map(m=>[m.month,m.assets])]},{name:'Dívida',data:[[0,month0.debt],...r.months.map(m=>[m.month,m.debt])]},{name:'Patrimônio dos carros',data:[[0,month0.assets-month0.debt],...r.months.map(m=>[m.month,m.assets-m.debt])]}]},'sim-cash':{max:params.horizon,series:[{name:'Caixa',data:[[0,month0.cash],...r.months.map(m=>[m.month,m.cash])]},{name:'Reserva',data:[[0,month0.reserve],...r.months.map(m=>[m.month,m.reserve])]}]},'sim-equity':{max:params.horizon,series:[{name:'Patrimônio',data:[[0,month0.equity],...r.months.map(m=>[m.month,m.equity])]},{name:'Capital próprio',data:[[0,params.initialCapital],...r.months.map(m=>[m.month,m.capital])]}]},'sim-fleet':{max:params.horizon,unit:'carros',step:true,series:[{name:'Frota',data:[[0,month0.fleet],...r.months.map(m=>[m.month,m.fleet])]}]}};}
 function drawCharts(){const defs=chartDefinitions(),colors=['#21865e','#91b3a0','#8fa7c3','#bd9861','#76827c'];root.querySelectorAll('[data-chart]').forEach(svg=>{const cfg=defs[svg.dataset.chart];if(!cfg)return;const width=Math.max(220,Math.round(svg.getBoundingClientRect().width)),height=220,left=50,right=14,top=15,bottom=30,points=cfg.series.flatMap(s=>s.data),low=Math.min(0,...points.map(d=>d[1])),high=Math.max(1,...points.map(d=>d[1])),span=high-low,lo=low-span*.05,hi=high+span*.10,x=n=>left+n/cfg.max*(width-left-right),y=n=>top+(hi-n)/(hi-lo)*(height-top-bottom),ticks=[...new Set([0,Math.round(cfg.max/2),cfg.max])],format=n=>cfg.unit==='carros'?num(n):Math.abs(n)>=1000?num(n/1000)+' mil':num(n);svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.innerHTML=`<title>${esc(svg.getAttribute('aria-label'))}</title><desc>Dados de simulação ou registros ilustrativos. Os valores exatos estão nas tabelas e nas memórias.</desc>${[low,(high+low)/2,high].map(n=>`<line x1="${left}" y1="${y(n)}" x2="${width-right}" y2="${y(n)}" stroke="#e7ede8"/><text x="${left-7}" y="${y(n)+4}" text-anchor="end">${format(n)}</text>`).join('')}${cfg.series.map((s,i)=>{const path=s.data.map((d,j)=>j?(cfg.step?`H${x(d[0])}V${y(d[1])}`:`L${x(d[0])},${y(d[1])}`):`M${x(d[0])},${y(d[1])}`).join(' ');return `<path d="${path}" fill="none" stroke="${colors[i]}" stroke-width="2.1" ${i===1&&svg.dataset.chart==='sim-cash'?'stroke-dasharray="4 4"':''}/>${s.data.filter((_,j)=>s.data.length<15||j===s.data.length-1).map(d=>`<circle cx="${x(d[0])}" cy="${y(d[1])}" r="2.5" fill="${colors[i]}"><title>${s.name} · mês ${d[0]}: ${cfg.unit==='carros'?num(d[1]):money(d[1])}</title></circle>`).join('')}`;}).join('')}${ticks.map((n,i)=>`<text x="${x(n)}" y="${height-12}" text-anchor="${i===0?'start':i===ticks.length-1?'end':'middle'}">${n}</text>`).join('')}<text x="${width-right}" y="${height-1}" text-anchor="end">Mês</text>`;});}
 function expenseForm(){return `<form id="expense-form"><div class="fields">${select('category','Natureza','opex',[['opex','Despesa operacional'],['contribution','Aporte do proprietário'],['tax','Tributo'],['interest','Juros'],['principal','Principal de financiamento']])}${input('amount','Valor · R$',250,'type="number" min=".01" step=".01" required')}${input('source','Origem e motivo','','required maxlength="120" placeholder="Ex.: OS-001 · troca de pneus"')}${select('month','Fechamento','3',[1,2,3].map(m=>[String(m),S.label(ops.book.calendar,m)]))}</div><p class="caption">Registro no livro demonstrativo. Uma despesa reduz o caixa e muda a comparação, preservando o plano.</p><div class="form-actions"><button type="submit" class="btn primary">Registrar lançamento</button></div></form>`;}
 function saleForm(){return `<form id="sale-form"><div class="fields">${select('productId','Produto','perfume',ops.book.products.map(p=>[p.id,p.name]))}${input('qty','Quantidade',1,'type="number" min="1" step="1" required')}${select('method','Quem recebeu o pagamento?','driver',[['driver','Motorista · dinheiro'],['company','Empresa · pagamento ilustrativo']])}</div><p class="caption">O kit é atualizado na venda. Custo, preço, comissão e quem recebeu ficam preservados no registro.</p><div class="form-actions"><button type="submit" class="btn primary">Confirmar venda demonstrativa</button></div></form>`;}
 function requestsBody(){return (ops.requests.length?ops.requests.map(r=>row(r.id+' · '+({maintenance:'Manutenção',stock:'Reposição',support:'Atendimento'}[r.type]),tag(r.status==='open'?'Aberto':r.status==='delivered'?'Entregue':r.status==='answered'?'Respondido':'Em atendimento',r.status==='open'?'amber':'green'),esc(r.note))+(r.status==='open'?btn(r.type==='stock'?'Conferir e transferir kit':'Iniciar atendimento','resolve-request','',`data-id="${r.id}"`):'')+(r.type!=='stock'?btn('Registrar resposta','reply-request','',`data-id="${r.id}"`):'')+(r.reply?`<p class="caption">Resposta: ${esc(r.reply)}</p>`:'')).join(''):'<p class="caption">Nenhuma solicitação nesta sessão. Os pedidos do app do motorista aparecem aqui.</p>')+panel('Vistorias de exemplo',ops.checklists.length?ops.checklists.map(v=>row(v.id,num(v.km)+' km',esc(v.note)||'Checklist conferido.')).join(''):'<p class="caption">Ainda sem checklist registrado.</p>');}
 function contractBody(){return row('Contrato','LOC-001 · exemplo')+row('Veículo','RV-001 · '+ops.vehicle.plate)+row('Motorista do vínculo','Marcos Oliveira')+row('Aluguel semanal',cash(ops.book.contract.weekly))+row('Kit comercial','Perfumes, carregadores e cabos','Comissão demonstrativa de '+ops.book.contract.commissionPct+'%; repasse separado do aluguel.')+row('Responsabilidades','A definir antes da contratação','Manutenção, franquia, seguro, limites de km, caução, atraso e rescisão precisam de condições acordadas.')+'<div class="notice amber gap">Esta ficha não é um contrato assinado. Minuta, aditivos, arquivos privados e assinatura precisam ser implementados e revisados antes da operação real.</div>';}
 root.addEventListener('click',event=>{const e=event.target.closest('button');if(!e)return;try{
  if(e.dataset.page){page=e.dataset.page;mode='admin';root.classList.remove('menu-open');close();render();persist();return;}
  if(e.dataset.mode){mode=e.dataset.mode;render();persist();return;}
  if(e.dataset.driverPage){driverPage=e.dataset.driverPage;mode='driver';render();persist();return;}
  if(e.dataset.driverLayout){driverLayout=e.dataset.driverLayout;render();return;}
  if(e.dataset.financeTab){financeTab=e.dataset.financeTab;render();return;}
  if(e.dataset.flowMode){flowMode=e.dataset.flowMode;updateSimulatorResults();return;}
  const action=e.dataset.action;if(!action)return;if(simulatorAction(action,e)||driverAction(action,e))return;
  if(action==='close'){close();return;}
  if(action==='menu'){const opened=root.classList.toggle('menu-open');e.setAttribute('aria-expanded',String(opened));return;}
  if(action.startsWith('go-')){page=action.slice(3);mode='admin';close();render();persist();return;}
  if(action==='add-driver'){open('Novo motorista no kanban',driverForm());return;}
  if(action==='driver-detail'){open('Ficha do motorista',driverForm(M.driver(ops,e.dataset.id)));return;}
  if(action==='expense'){open('Novo lançamento',expenseForm());return;}
  if(action==='pay'){const ok=M.pay(ops,e.dataset.id);revision=null;render();persist();toast(ok?'Recebimento conferido. Caixa e realizado atualizados.':'Esse recebimento já estava conferido.');return;}
  if(action==='sale'){open('Venda no kit · RV-001',saleForm());return;}
  if(action==='stock-transfer'){const p=ops.book.products.find(p=>p.id===e.dataset.id);open('Transferir para o carro',`<form id="transfer-form"><input type="hidden" name="productId" value="${p.id}">${row(esc(p.name),p.central+' un. na central')}${input('qty','Quantidade a transferir',1,'type="number" min="1" step="1" required')}<div class="form-actions"><button type="submit" class="btn primary">Conferir transferência</button></div></form>`);return;}
  if(action==='settle'){const ok=M.settle(ops);revision=null;render();persist();toast(ok?'Acerto conferido uma vez e incluído no financeiro.':'Não há vendas pendentes de acerto.');return;}
  if(action==='requests'){open('Solicitações e vistorias',requestsBody());return;}
  if(action==='resolve-request'){M.resolve(ops,e.dataset.id);open('Solicitações e vistorias',requestsBody());persist();return;}
  if(action==='reply-request'){open('Responder na demonstração',`<form id="reply-form"><input type="hidden" name="entityId" value="${e.dataset.id}"><label class="field">Resposta<textarea name="message" required rows="3" maxlength="1000"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Salvar resposta no exemplo</button></div></form>`);return;}
  if(action==='service-open'){open('Abrir manutenção',`<form id="service-form">${select('vehicleId','Veículo','RV-001',M.vehicles(ops).map(v=>[v.id,v.id+' · '+v.model]))}${input('title','Serviço necessário','','required maxlength="150" placeholder="Ex.: revisão de 45.000 km"')}<div class="form-actions"><button type="submit" class="btn primary">Abrir ordem e marcar indisponibilidade</button></div></form>`);return;}
  if(action==='service-close'){open('Concluir manutenção',`<form id="service-close-form"><input type="hidden" name="entityId" value="${e.dataset.id}">${input('cost','Custo final · R$',250,'type="number" min="0" step=".01" required')}<div class="form-actions"><button type="submit" class="btn primary">Concluir e lançar uma vez</button></div></form>`);return;}
  if(action==='acquire'){open('Registrar um carro no realizado',`<form id="acquire-form"><div class="fields">${input('model','Modelo do veículo','','required maxlength="100" placeholder="Ex.: Chevrolet Onix"')}${input('plate','Identificação ou placa','','maxlength="20" placeholder="Pode cadastrar depois"')}${input('price','Preço de compra · R$',params.price,'type="number" min="1" required')}${input('downPct','Entrada · %',params.downPct,'type="number" min="0" max="100" required')}${input('month','Mês do fechamento · 1 a 3',3,'type="number" min="1" max="3" step="1" required')}</div><p class="caption">As condições de financiamento, preparação e estoque usam o cenário atual. Não realiza compra nem crédito: cria apenas um ativo de demonstração, com saída de caixa e dívida rastreáveis.</p><div class="form-actions"><button type="submit" class="btn primary">Registrar aquisição demonstrativa</button></div></form>`);return;}
  if(action==='contract'){open('Contrato e responsabilidades',contractBody());return;}
  if(action==='ledger'){financeTab='ledger';page='finance';mode='admin';close();render();return;}
  if(action==='cash-source'){open('Composição do caixa no fechamento',actualCashBody());return;}
  if(action==='metric-source'){const a=actual();open('Origem · '+e.dataset.key,e.dataset.key==='cash'?actualCashBody():e.dataset.key==='equity'?row('Caixa',money(a.cash))+row('Carros estimados',money(a.assets))+row('Estoque estimado',money(a.inventory))+row('Dívida',money(-a.debt))+row('Patrimônio',money(a.equity),'',true):e.dataset.key==='fleet'?row('Frota registrada',a.fleet+' carros','Compras do simulador não geram carros reais automaticamente.'):ledgerView());return;}
  if(action==='revise'){const a=actual();revision=S.simulate({...params,horizon:Math.max(params.horizon,a.month+1)},a.snapshot);render();toast('Futuro reestimado a partir de '+a.label+'. Plano original preservado.');return;}
  if(action==='freeze'){savedScenarios.push({name:'Referência anterior · '+baseline.id,params:structuredClone(baseline.params),at:baseline.createdAt});baseline=S.freezePlan(params,'PLANO-'+String(savedScenarios.length+2).padStart(3,'0'));savedScenarios.push({name:scenarioName+' · referência',params:structuredClone(params),at:new Date().toISOString()});M.log(ops,'Plano preservado',baseline.id);revision=null;render();persist();toast('Nova referência preservada. Os registros financeiros não foram alterados.');return;}
  if(action==='history'){open('Histórico e dados locais',table(['Evento','Quando','Detalhe'],[...ops.events,...ops.book.audit].slice(0,70).map(v=>`<tr><td>${esc(v.action)}</td><td>${esc(new Date(v.at).toLocaleString('pt-BR'))}</td><td>${esc(v.detail||v.details)}</td></tr>`).join(''))||'<p>Sem eventos.</p>');return;}
  if(action==='search'){open('Buscar na operação',`<form id="search-form">${input('query','Motorista, placa ou contrato','','required placeholder="Ex.: Marcos, RV-001 ou LOC-001"')}<div class="form-actions"><button type="submit" class="btn primary">Buscar</button></div></form>`);return;}
  if(action==='about'){open('Como usar esta versão',`<div class="notice">Nova proposta RODAVOLT, reconstruída em 18/10/2026. Tudo aqui é demonstrativo e local.</div>${row('Operação','Brasil · BRL','Aluguel semanal para motoristas de aplicativo.')}${row('Exemplo financeiro','Novembro/2026 a janeiro/2027','Período futuro ilustrativo; não são transações existentes.')}${row('Dados','Salvos neste navegador','A versão anterior não é importada nem sobrescrita. Exporte antes de trocar de dispositivo.')}${row('Integrações','Ainda não conectadas','Banco, Pix, autenticação, arquivos e Uber/99 não estão ligados.')}${row('Referências pesquisadas','Fleetio, Fleetbase e Kanboard','Organização do fluxo de manutenção, operação e kanban; implementação própria.')}<p class="caption">A rotina, o simulador, o kanban e os fluxos entre motorista e gestão podem ser explorados. Antes de usar em produção: banco com permissões, contratos reais, conciliação, arquivos privados e homologação.</p>`);return;}
  if(action==='export-data'){download('rodavolt-dados-locais.json',JSON.stringify({version:3,params,baseline:{id:baseline.id,params:baseline.params},ops,savedScenarios},null,2),'application/json');return;}
 }catch(error){reportError(error.message);}});
 function actualCashBody(){const a=actual();return row('Caixa de abertura',money(a.openingCash),esc(ops.book.openingStockSource||'Posição inicial conferida no exemplo.'))+row('Aluguéis recebidos',money(a.rentalReceived))+row('Vendas brutas',money(a.storeGross))+row('Parcelas',money(-a.debtService))+row('Despesas operacionais',money(-a.opex))+row('Outras saídas e aportes','Ver livro','Mercadoria, comissão, tributo, capex e aportes têm categoria própria.')+row('Caixa final',money(a.cash),'Saldo obtido pelos registros confirmados.',true)+ledgerView();}
 root.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const f=new FormData(form),n=k=>Number(f.get(k));try{if(simulatorSubmit(form,f)||driverSubmit(form,f))return;
  if(form.id==='driver-form'){if(f.get('entityId')){const candidate=structuredClone(ops),d=M.driver(candidate,f.get('entityId'));d.name=String(f.get('name')).trim();if(d.name.length<2||d.name.length>100)throw new RangeError('Informe um nome entre 2 e 100 caracteres.');d.note=String(f.get('note')).trim();d.interest=String(f.get('interest')).trim();d.due=String(f.get('due'));d.nextVehicleId=String(f.get('nextVehicleId'));for(const key of ['docs','signed','inspection'])d[key]=f.has(key);M.move(candidate,d.id,f.get('stage'));ops=candidate;}else M.addDriver(ops,Object.fromEntries(f));}
  else if(form.id==='expense-form'){C.addEntry(ops.book,{category:f.get('category'),month:n('month'),amount:n('amount'),source:f.get('source'),vehicle:'RV-001'});revision=null;}
  else if(form.id==='sale-form'){C.sale(ops.book,f.get('productId'),n('qty'),f.get('method'));}
  else if(form.id==='transfer-form'){C.transfer(ops.book,f.get('productId'),n('qty'));}
  else if(form.id==='reply-form'){M.reply(ops,f.get('entityId'),f.get('message'));}
  else if(form.id==='service-form'){M.openService(ops,{title:f.get('title'),vehicleId:f.get('vehicleId')});}
  else if(form.id==='service-close-form'){M.closeService(ops,f.get('entityId'),n('cost'));revision=null;}
  else if(form.id==='acquire-form'){M.acquire(ops,{...params,purchaseMonth:n('month'),price:n('price'),downPct:n('downPct'),model:f.get('model'),plate:f.get('plate')});revision=null;}
  else if(form.id==='search-form'){const q=String(f.get('query')).trim().toLowerCase(),found=ops.drivers.filter(d=>(d.name+' '+d.note).toLowerCase().includes(q)),car=(ops.vehicle.model+' '+ops.vehicle.id+' '+ops.vehicle.plate).toLowerCase().includes(q),contract='loc-001'.includes(q);open('Resultados da busca',found.map(d=>row(esc(d.name),M.stages.find(([k])=>k===d.stage)[1])+btn('Abrir ficha','driver-detail','',`data-id="${d.id}"`)).join('')+(car?row(ops.vehicle.model,ops.vehicle.plate)+btn('Ver carro','go-fleet'):'')+(contract?row('LOC-001','Contrato de exemplo')+btn('Abrir condições','contract'):'')+(!found.length&&!car&&!contract?'<p class="caption">Nenhum resultado para esse termo.</p>':''));return;}
  else return;close();render();persist();toast('Registro salvo nesta demonstração local.');
 }catch(error){reportError(error.message);}});
 root.addEventListener('input',event=>{const e=event.target;if(e.closest('#sim-form')){clearTimeout(simTimer);simTimer=setTimeout(readSimulator,250);}if(e.dataset.driverFilter){driverFilter=e.value;const selection=e.selectionStart;const holder=root.querySelector('#driver-board');const fresh=document.createElement('div');fresh.innerHTML=drivers();holder.innerHTML=fresh.querySelector('#driver-board').innerHTML;e.focus();if(selection!==null)e.setSelectionRange(selection,selection);}if(e.closest('#ride-form'))updateRide();});
 root.addEventListener('change',event=>{const e=event.target;if(e.dataset.period){const fromDialog=dialog.contains(e);month=Number(e.value);revision=null;render();if(fromDialog)open('Livro de registros',ledgerView());}if(e.closest('#sim-form')){clearTimeout(simTimer);readSimulator();}if(e.closest('#ride-form'))updateRide();});
 root.addEventListener('dragstart',event=>{const card=event.target.closest('[data-driver-card]');if(!card)return;draggedId=card.dataset.driverCard;event.dataTransfer.setData('text/plain',draggedId);event.dataTransfer.effectAllowed='move';});
 root.addEventListener('dragover',event=>{const lane=event.target.closest('[data-stage]');if(!lane||!draggedId)return;event.preventDefault();lane.classList.add('drag-over');});
 root.addEventListener('dragleave',event=>{const lane=event.target.closest('[data-stage]');if(lane&&!lane.contains(event.relatedTarget))lane.classList.remove('drag-over');});
 root.addEventListener('drop',event=>{const lane=event.target.closest('[data-stage]');if(!lane||!draggedId)return;event.preventDefault();try{M.move(ops,draggedId,lane.dataset.stage);render();persist();toast('Etapa atualizada no fluxo do motorista.');}catch(error){lane.classList.remove('drag-over');toast(error.message);}draggedId=null;});
 root.addEventListener('dragend',()=>{draggedId=null;root.querySelectorAll('.drag-over').forEach(e=>e.classList.remove('drag-over'));});
 let resizeTimer;if(globalThis.ResizeObserver)new ResizeObserver(()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(drawCharts,80);}).observe(main);
 try{if(!isQA)restore(JSON.parse(localStorage.getItem(storageKey)||'null'));}catch{}
 render();
})();
